-- V3 ROLLBACK REHEARSAL ONLY. DO NOT RUN IN PRODUCTION.
-- This script performs transactional DDL, then ALWAYS ROLLS BACK on success.
-- NOT production-ready: permission and tenant-isolation tests are still required.
BEGIN;
DO $history_guard$
BEGIN
  IF EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version = '20261118000900') THEN
    RAISE EXCEPTION 'Migration 20261118000900 already recorded; stop';
  END IF;
END;
$history_guard$;

-- FORWARD-ONLY, UNDEPLOYED. Requires native 0000-0007, not vehicle draft 0008.
-- Native executor must commit this whole file and its history INSERT atomically.
-- No backfill: a mutable legacy row cannot establish its original creation payload.
SET LOCAL search_path=pg_catalog,pg_temp;
DO $guard$
BEGIN
 IF session_user<>'postgres' OR current_user<>'postgres' THEN RAISE EXCEPTION 'Migration identity mismatch'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_class WHERE oid IN (
   'identity.supabase_users'::pg_catalog.regclass,'identity.users'::pg_catalog.regclass,
   'tenancy.agencies'::pg_catalog.regclass,'tenancy.memberships'::pg_catalog.regclass,
   'tenancy.roles'::pg_catalog.regclass,'tenancy.membership_roles'::pg_catalog.regclass,'tenancy.role_permissions'::pg_catalog.regclass)
   AND relrowsecurity AND relforcerowsecurity)<>7
 THEN RAISE EXCEPTION 'Receipt metadata RLS boundary mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid='tenancy.clients'::pg_catalog.regclass
   AND relowner='postgres'::pg_catalog.regrole AND relrowsecurity AND relforcerowsecurity)
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='contratpro_client_receipt_writer')
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid='auth.uid()'::pg_catalog.regprocedure AND prosecdef)
 -- Managed auth.uid inherits our trusted path unless it has its own safe path.
 -- Do not alter provider functions or assume their ACLs are grantable by postgres.
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p,LATERAL pg_catalog.unnest(p.proconfig) setting
   WHERE p.oid='auth.uid()'::pg_catalog.regprocedure AND setting LIKE 'search_path=%'
   AND setting NOT IN ('search_path=pg_catalog, pg_temp','search_path=pg_catalog,pg_temp'))
 OR (SELECT count(*) FROM pg_catalog.pg_trigger WHERE tgrelid='tenancy.clients'::pg_catalog.regclass AND NOT tgisinternal)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid
   WHERE t.tgrelid='tenancy.clients'::pg_catalog.regclass AND t.tgname='clients_guard' AND t.tgtype=23 AND t.tgenabled='O'
   AND p.oid='app_private.client_guard()'::pg_catalog.regprocedure AND NOT p.prosecdef AND p.proowner='postgres'::pg_catalog.regrole)
 THEN RAISE EXCEPTION 'Client receipt deployment boundary mismatch'; END IF;
END;
$guard$;

-- Local candidate: narrow SECURITY DEFINER bridge for Supabase-managed auth.uid().
-- Its only output is the current request JWT subject, never a privileged user lookup.
CREATE FUNCTION app_private.receipt_auth_uid() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $receipt_auth_uid$ SELECT auth.uid() $receipt_auth_uid$;
ALTER FUNCTION app_private.receipt_auth_uid() OWNER TO postgres;
-- PostgreSQL grants EXECUTE to PUBLIC by default for newly created functions.
REVOKE ALL ON FUNCTION app_private.receipt_auth_uid() FROM PUBLIC;
-- Existing canonical_auth_user() EXECUTE ACL observed in Production:
-- postgres, authenticated, contratpro_agency_writer. No PUBLIC grant.
-- Other internal callers must be checked before expanding this list.
GRANT EXECUTE ON FUNCTION app_private.receipt_auth_uid() TO authenticated,contratpro_agency_writer;
-- canonical_auth_user is SECURITY INVOKER: route only its auth.uid call through bridge.
CREATE OR REPLACE FUNCTION app_private.canonical_auth_user() RETURNS uuid
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $canonical$
 SELECT u.id FROM identity.supabase_users link JOIN identity.users u ON u.id=link.user_id
 WHERE link.supabase_user_id=(SELECT app_private.receipt_auth_uid()) AND u.state='active'
$canonical$;

-- Deliberate forward-only proconfig hardening of the shared invoker call chain.
-- NOTE: canonical_auth_user body IS changed above; regression testing required.
ALTER FUNCTION app_private.canonical_auth_user() SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION app_private.agency_owner(uuid) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION app_private.client_allowed(uuid,text) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION app_private.client_payload(tenancy.clients) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION app_private.client_guard() SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION public.contratpro_clients_permissions(uuid) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION public.contratpro_clients_list(uuid,text,text,integer,integer) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION public.contratpro_client_detail(uuid,uuid) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION public.contratpro_client_update(uuid,uuid,integer,jsonb) SET search_path=pg_catalog,pg_temp;
ALTER FUNCTION public.contratpro_client_archive(uuid,uuid,integer) SET search_path=pg_catalog,pg_temp;

-- Dedicated least-privilege owner: existing agency-writer policies are owner-only
-- and cannot safely serve permissioned non-owner client creators.
CREATE ROLE contratpro_client_receipt_writer NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
GRANT contratpro_client_receipt_writer TO postgres WITH ADMIN FALSE, INHERIT FALSE, SET TRUE GRANTED BY postgres;
GRANT USAGE ON SCHEMA identity,tenancy,app_private TO contratpro_client_receipt_writer;
GRANT EXECUTE ON FUNCTION app_private.receipt_auth_uid() TO contratpro_client_receipt_writer;
GRANT CREATE ON SCHEMA app_private TO contratpro_client_receipt_writer;
GRANT SELECT(supabase_user_id,user_id) ON identity.supabase_users TO contratpro_client_receipt_writer;
GRANT SELECT(id,state) ON identity.users TO contratpro_client_receipt_writer;
GRANT SELECT(id,state) ON tenancy.agencies TO contratpro_client_receipt_writer;
GRANT SELECT(id,agency_id,user_id,state) ON tenancy.memberships TO contratpro_client_receipt_writer;
GRANT SELECT(id,agency_id,key) ON tenancy.roles TO contratpro_client_receipt_writer;
GRANT SELECT ON tenancy.membership_roles,tenancy.role_permissions TO contratpro_client_receipt_writer;
GRANT EXECUTE ON FUNCTION app_private.canonical_auth_user(),app_private.agency_owner(uuid),
 app_private.client_allowed(uuid,text),app_private.client_payload(tenancy.clients) TO contratpro_client_receipt_writer;
CREATE POLICY receipt_mapping_read ON identity.supabase_users FOR SELECT TO contratpro_client_receipt_writer
 USING(supabase_user_id=(SELECT app_private.receipt_auth_uid()));
CREATE POLICY receipt_user_read ON identity.users FOR SELECT TO contratpro_client_receipt_writer
 USING(id IN (SELECT user_id FROM identity.supabase_users WHERE supabase_user_id=(SELECT app_private.receipt_auth_uid())));
CREATE POLICY receipt_membership_read ON tenancy.memberships FOR SELECT TO contratpro_client_receipt_writer
 USING(user_id=app_private.canonical_auth_user() AND state='active');
CREATE POLICY receipt_agency_read ON tenancy.agencies FOR SELECT TO contratpro_client_receipt_writer
 USING(EXISTS(SELECT 1 FROM tenancy.memberships m WHERE m.agency_id=tenancy.agencies.id AND m.state='active'));
CREATE POLICY receipt_role_read ON tenancy.roles FOR SELECT TO contratpro_client_receipt_writer
 USING(agency_id IN (SELECT agency_id FROM tenancy.memberships WHERE state='active'));
CREATE POLICY receipt_assignment_read ON tenancy.membership_roles FOR SELECT TO contratpro_client_receipt_writer
 USING(EXISTS(SELECT 1 FROM tenancy.memberships m WHERE m.id=membership_id AND m.agency_id=tenancy.membership_roles.agency_id AND m.state='active'));
CREATE POLICY receipt_permission_read ON tenancy.role_permissions FOR SELECT TO contratpro_client_receipt_writer
 USING(EXISTS(SELECT 1 FROM tenancy.membership_roles mr WHERE mr.role_id=tenancy.role_permissions.role_id AND mr.agency_id=tenancy.role_permissions.agency_id));

-- SHA-256 is NOT PII anonymization. Confidentiality is provided by privileges/RLS.
-- Store no plaintext duplicate, no public fingerprint column and no HMAC secret.
CREATE TABLE app_private.client_creation_receipts (
 agency_id uuid NOT NULL,
 creation_key uuid NOT NULL,
 creator_user_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE RESTRICT,
 client_id uuid NOT NULL,
 format_version integer NOT NULL DEFAULT 1 CHECK(format_version=1),
 original_digest bytea NOT NULL CHECK(octet_length(original_digest)=32),
 PRIMARY KEY(agency_id,creation_key),
 UNIQUE(agency_id,client_id),
 FOREIGN KEY(agency_id,client_id) REFERENCES tenancy.clients(agency_id,id) ON DELETE RESTRICT
);
ALTER TABLE app_private.client_creation_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE app_private.client_creation_receipts FORCE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.client_creation_receipts FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer,contratpro_client_receipt_writer;
-- Default ACLs can name roles outside the fixed application-role list. Remove
-- every non-owner grant on this new object before installing its allowlist.
DO $receipt_acl$
DECLARE grantee_name pg_catalog.text;
BEGIN
 FOR grantee_name IN
   SELECT DISTINCT pg_catalog.pg_get_userbyid(a.grantee)
   FROM pg_catalog.pg_class c,LATERAL pg_catalog.aclexplode(c.relacl) a
   WHERE c.oid='app_private.client_creation_receipts'::pg_catalog.regclass
     AND a.grantee<>c.relowner AND a.grantee<>0
 LOOP
   EXECUTE pg_catalog.format('REVOKE ALL ON TABLE app_private.client_creation_receipts FROM %I',grantee_name);
 END LOOP;
END;
$receipt_acl$;
GRANT SELECT,INSERT ON app_private.client_creation_receipts TO contratpro_client_receipt_writer;
CREATE POLICY client_receipts_read ON app_private.client_creation_receipts FOR SELECT TO contratpro_client_receipt_writer
 USING(creator_user_id=app_private.canonical_auth_user() AND app_private.client_allowed(agency_id,'clients.read') AND app_private.client_allowed(agency_id,'clients.create'));
CREATE POLICY client_receipts_insert ON app_private.client_creation_receipts FOR INSERT TO contratpro_client_receipt_writer
 WITH CHECK(creator_user_id=app_private.canonical_auth_user() AND app_private.client_allowed(agency_id,'clients.read') AND app_private.client_allowed(agency_id,'clients.create'));
-- There are deliberately no UPDATE/DELETE grants or policies, including archive.

