BEGIN
 IF p IS NULL OR upper_case IS NULL OR pg_catalog.octet_length(p)>1280 OR pg_catalog.length(p)>320
 THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 chars:=pg_catalog.string_to_array(p,NULL);
 FOR i IN 1..COALESCE(pg_catalog.array_length(chars,1),0) LOOP
   IF NOT upper_case AND chars[i]='Σ' THEN
     j:=i-1;
     WHILE j>=1 AND pg_catalog.ascii(chars[j]) <@ ignored LOOP j:=j-1; END LOOP;
     before_cased:=j>=1 AND pg_catalog.ascii(chars[j]) <@ cased;
     j:=i+1;
     WHILE j<=pg_catalog.array_length(chars,1) AND pg_catalog.ascii(chars[j]) <@ ignored LOOP j:=j+1; END LOOP;
     after_cased:=j<=pg_catalog.array_length(chars,1) AND pg_catalog.ascii(chars[j]) <@ cased;
     answer:=answer||CASE WHEN before_cased AND NOT after_cased THEN 'ς' ELSE 'σ' END;
   ELSE answer:=answer||COALESCE((CASE WHEN upper_case THEN upper_map ELSE lower_map END)->>chars[i],chars[i]); END IF;
 END LOOP;
 RETURN answer;
END;
$case_fn$;
REVOKE ALL ON FUNCTION app_private.client_unicode_case(pg_catalog.text,pg_catalog.bool) FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
GRANT EXECUTE ON FUNCTION app_private.client_unicode_case(pg_catalog.text,pg_catalog.bool) TO authenticated,contratpro_client_receipt_writer;
-- END GENERATED CLIENT UNICODE V1

CREATE FUNCTION app_private.normalize_client_creation(p pg_catalog.jsonb) RETURNS pg_catalog.jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $f$
DECLARE result pg_catalog.jsonb:='{}'::pg_catalog.jsonb; k pg_catalog.text; v pg_catalog.text; units pg_catalog.int4;
 fields pg_catalog.text[]:=ARRAY['firstName','lastName','phone','email','nationality','identityType','identityNumber','licenceNumber','licenceIssueDate','licenceExpiryDate','address','city','notes'];
 limits pg_catalog.int4[]:=ARRAY[100,100,16,320,80,8,30,40,10,10,400,100,2000]; i pg_catalog.int4; d pg_catalog.date;
 trim_chars pg_catalog.text:=U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
BEGIN
 -- JSONB parsing belongs to PostgreSQL/PostgREST; bound our own processing before
 -- expanding fields or running Unicode loops. Canonical valid payloads fit easily.
 IF p IS NULL OR pg_catalog.jsonb_typeof(p)<>'object' OR pg_catalog.pg_column_size(p)>32768
 THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 IF pg_catalog.octet_length(p::pg_catalog.text)>32768 OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_each(p) e
   WHERE NOT(e.key=ANY(fields)) OR pg_catalog.jsonb_typeof(e.value)<>'string')
 THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 FOR i IN 1..pg_catalog.array_length(fields,1) LOOP
   k:=fields[i]; v:=COALESCE(p->>k,CASE WHEN k='identityType' THEN 'none' ELSE '' END);
   IF pg_catalog.octet_length(v)>8192 THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   v:=pg_catalog.btrim(v,trim_chars);
   IF pg_catalog.length(v)>limits[i] THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   SELECT COALESCE(sum(CASE WHEN pg_catalog.ascii(pg_catalog.substr(v,n,1))>65535 THEN 2 ELSE 1 END),0) INTO units FROM pg_catalog.generate_series(1,pg_catalog.length(v)) n;
   IF units>limits[i] OR (k<>'notes' AND v COLLATE pg_catalog."C" ~ U&'[\0001-\001F\007F]')
     OR (k='notes' AND v COLLATE pg_catalog."C" ~ U&'[\0001-\0008\000B\000C\000E-\001F\007F]')
   THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   IF k IN ('email','identityNumber','licenceNumber') THEN
     v:=app_private.client_unicode_case(v,k<>'email');
     SELECT COALESCE(sum(CASE WHEN pg_catalog.ascii(pg_catalog.substr(v,n,1))>65535 THEN 2 ELSE 1 END),0) INTO units FROM pg_catalog.generate_series(1,pg_catalog.length(v)) n;
     IF units>limits[i] THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   END IF;
   result:=result||pg_catalog.jsonb_build_object(k,v);
 END LOOP;
 IF result->>'firstName'='' OR result->>'lastName'='' OR (result->>'phone') COLLATE pg_catalog."C" !~ '^\+?[0-9]{8,15}$'
 OR (result->>'email'<>'' AND ((result->>'email') COLLATE pg_catalog."C" !~ '^[^@]+@[^@]+\.[^@]+$' OR (result->>'email') COLLATE pg_catalog."C" ~ ('['||trim_chars||']')))
 OR result->>'identityType' NOT IN ('none','cin','passport')
 OR (result->>'identityType'='none' AND result->>'identityNumber'<>'')
 OR (result->>'identityType'='cin' AND (result->>'identityNumber') COLLATE pg_catalog."C" !~ '^[A-Z0-9]{4,20}$')
 OR (result->>'identityType'='passport' AND (result->>'identityNumber') COLLATE pg_catalog."C" !~ '^[A-Z0-9-]{4,30}$')
 THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 IF result->>'licenceNumber'='' THEN
   IF result->>'licenceIssueDate'<>'' OR result->>'licenceExpiryDate'<>'' THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 ELSE
   IF (result->>'licenceNumber') COLLATE pg_catalog."C" !~ '^[A-Z0-9][A-Z0-9 /-]{2,39}$' THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   FOREACH k IN ARRAY ARRAY['licenceIssueDate','licenceExpiryDate'] LOOP
     IF (result->>k) COLLATE pg_catalog."C" !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
     d:=(result->>k)::pg_catalog.date;
     IF d<DATE '1900-01-01' OR d>DATE '2199-12-31' OR pg_catalog.to_char(d,'YYYY-MM-DD')<>result->>k THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
   END LOOP;
   IF (result->>'licenceIssueDate')::pg_catalog.date>(pg_catalog.now() AT TIME ZONE 'UTC')::pg_catalog.date
   OR (result->>'licenceExpiryDate')::pg_catalog.date<(result->>'licenceIssueDate')::pg_catalog.date THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN result;
EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format OR invalid_text_representation THEN
 RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023';
END;
$f$;
REVOKE ALL ON FUNCTION app_private.normalize_client_creation(jsonb) FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
GRANT EXECUTE ON FUNCTION app_private.normalize_client_creation(jsonb) TO authenticated,contratpro_client_receipt_writer;

-- Forward-only validation wrapper: existing guard/update paths share exactly this
-- normalization/validation contract; no privileged call to the legacy validator.
CREATE OR REPLACE FUNCTION app_private.valid_client(p pg_catalog.jsonb) RETURNS pg_catalog.bool
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $valid$
BEGIN
 PERFORM app_private.normalize_client_creation(p); RETURN true;
EXCEPTION WHEN invalid_parameter_value THEN RETURN false;
END;
$valid$;

-- AFTER INSERT sees the actual guarded/normalized inserted row. PostgreSQL cannot
-- call a trigger-returning function directly; callers cannot forge a receipt.
CREATE FUNCTION app_private.capture_client_creation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $f$
BEGIN
 IF TG_RELID<>'tenancy.clients'::pg_catalog.regclass OR TG_OP<>'INSERT' OR TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW'
   OR NEW.created_by_user_id IS DISTINCT FROM app_private.canonical_auth_user()
 THEN RAISE EXCEPTION 'Denied' USING ERRCODE='42501'; END IF;
 INSERT INTO app_private.client_creation_receipts(agency_id,creation_key,creator_user_id,client_id,original_digest)
 VALUES(NEW.agency_id,NEW.creation_key,NEW.created_by_user_id,NEW.id,
   sha256(convert_to(jsonb_build_object('format',1,'domain','contratpro.client-create.v1','agency',NEW.agency_id,'key',NEW.creation_key,
     'creator',NEW.created_by_user_id,'details',app_private.normalize_client_creation(app_private.client_payload(NEW)))::pg_catalog.text,'UTF8')));
 RETURN NULL;
END;
$f$;
REVOKE ALL ON FUNCTION app_private.capture_client_creation() FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
-- Normalize inherited default grants while postgres still owns the function.
DO $capture_acl$
DECLARE grantee_name pg_catalog.text;
BEGIN
 FOR grantee_name IN
   SELECT DISTINCT pg_catalog.pg_get_userbyid(a.grantee)
   FROM pg_catalog.pg_proc p,LATERAL pg_catalog.aclexplode(p.proacl) a
   WHERE p.oid='app_private.capture_client_creation()'::pg_catalog.regprocedure
     AND a.grantee<>p.proowner AND a.grantee<>0
 LOOP
   EXECUTE pg_catalog.format('REVOKE ALL ON FUNCTION app_private.capture_client_creation() FROM %I',grantee_name);
 END LOOP;
END;
$capture_acl$;
-- Attach while postgres still owns the function (CREATE TRIGGER checks EXECUTE).
-- No DML runs in this migration; the trigger is only exposed after owner transfer.
CREATE TRIGGER clients_capture_creation AFTER INSERT ON tenancy.clients FOR EACH ROW EXECUTE FUNCTION app_private.capture_client_creation();
ALTER FUNCTION app_private.capture_client_creation() OWNER TO contratpro_client_receipt_writer;

-- Returns only equality/absence for this authorized creator, never a digest or ID.
CREATE FUNCTION app_private.match_client_creation(p_agency_id uuid,p_key uuid,p_normalized jsonb) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET row_security=on AS $f$
 SELECT r.original_digest=sha256(convert_to(jsonb_build_object('format',1,'domain','contratpro.client-create.v1','agency',p_agency_id,'key',p_key,
   'creator',app_private.canonical_auth_user(),'details',app_private.normalize_client_creation(p_normalized))::pg_catalog.text,'UTF8'))
 FROM app_private.client_creation_receipts r WHERE r.agency_id=p_agency_id AND r.creation_key=p_key
 AND r.creator_user_id=app_private.canonical_auth_user() AND r.format_version=1
$f$;
REVOKE ALL ON FUNCTION app_private.match_client_creation(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
DO $match_acl$
DECLARE grantee_name pg_catalog.text;
BEGIN
 FOR grantee_name IN
   SELECT DISTINCT pg_catalog.pg_get_userbyid(a.grantee)
   FROM pg_catalog.pg_proc p,LATERAL pg_catalog.aclexplode(p.proacl) a
   WHERE p.oid='app_private.match_client_creation(uuid,uuid,jsonb)'::pg_catalog.regprocedure
     AND a.grantee<>p.proowner AND a.grantee<>0
 LOOP
   EXECUTE pg_catalog.format('REVOKE ALL ON FUNCTION app_private.match_client_creation(uuid,uuid,jsonb) FROM %I',grantee_name);
 END LOOP;
END;
$match_acl$;
-- Finish ACLs while postgres owns the function: SET-only membership does not
-- inherit the new owner's grant authority.
GRANT EXECUTE ON FUNCTION app_private.match_client_creation(uuid,uuid,jsonb) TO authenticated;
ALTER FUNCTION app_private.match_client_creation(uuid,uuid,jsonb) OWNER TO contratpro_client_receipt_writer;

CREATE OR REPLACE FUNCTION public.contratpro_client_create(p_agency_id uuid,p_key uuid,p_details jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $f$
DECLARE cid pg_catalog.uuid; creator pg_catalog.uuid; row_creator pg_catalog.uuid; normalized pg_catalog.jsonb; matched pg_catalog.bool;
BEGIN
 creator:=app_private.canonical_auth_user();
 IF creator IS NULL OR NOT app_private.client_allowed(p_agency_id,'clients.read') OR NOT app_private.client_allowed(p_agency_id,'clients.create')
 THEN RAISE EXCEPTION 'Denied' USING ERRCODE='42501'; END IF;
 IF p_key IS NULL THEN RAISE EXCEPTION 'Invalid client fields' USING ERRCODE='22023'; END IF;
 normalized:=app_private.normalize_client_creation(p_details);
 PERFORM pg_advisory_xact_lock(hashtextextended('contratpro.client-create.v1:'||p_agency_id::pg_catalog.text||':'||p_key::pg_catalog.text,0));
 matched:=app_private.match_client_creation(p_agency_id,p_key,normalized);
 IF matched IS FALSE THEN RAISE EXCEPTION 'Creation conflict' USING ERRCODE='40001'; END IF;
 -- A replay needs read+create, not update/archive: do not use FOR UPDATE, whose
 -- RLS semantics would incorrectly hide rows from create-only members.
 -- This SELECT is the active-row linearization point; HTTP still reads back.
 SELECT id,created_by_user_id INTO cid,row_creator FROM tenancy.clients
 WHERE agency_id=p_agency_id AND creation_key=p_key AND state='active';
 IF FOUND THEN
   IF row_creator IS DISTINCT FROM creator OR matched IS DISTINCT FROM true
   THEN RAISE EXCEPTION 'Creation conflict' USING ERRCODE='40001'; END IF;
   RETURN cid;
 END IF;
 IF matched IS TRUE THEN RAISE EXCEPTION 'Client unavailable' USING ERRCODE='P0002'; END IF;
 INSERT INTO tenancy.clients(agency_id,creation_key,first_name,last_name,phone,email,nationality,identity_type,identity_number,licence_number,licence_issue_date,licence_expiry_date,address,city,notes)
 VALUES(p_agency_id,p_key,normalized->>'firstName',normalized->>'lastName',normalized->>'phone',normalized->>'email',normalized->>'nationality',
 normalized->>'identityType',normalized->>'identityNumber',normalized->>'licenceNumber',NULLIF(normalized->>'licenceIssueDate','')::pg_catalog.date,
 NULLIF(normalized->>'licenceExpiryDate','')::pg_catalog.date,normalized->>'address',normalized->>'city',normalized->>'notes')
 ON CONFLICT(agency_id,creation_key) DO NOTHING RETURNING id INTO cid;
 -- Includes archived legacy/other-creator keys and direct INSERT races. No ID leak.
 IF cid IS NULL THEN RAISE EXCEPTION 'Creation conflict' USING ERRCODE='40001'; END IF;
 RETURN cid;
END;
$f$;
REVOKE ALL ON FUNCTION public.contratpro_client_create(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
GRANT EXECUTE ON FUNCTION public.contratpro_client_create(uuid,uuid,jsonb) TO authenticated;
-- Data-free rollout marker: new application code refuses the old create contract.
CREATE FUNCTION public.contratpro_client_creation_contract() RETURNS integer
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $f$ SELECT 2 $f$;
REVOKE ALL ON FUNCTION public.contratpro_client_creation_contract() FROM PUBLIC,anon,authenticated,service_role,
 contratpro_migration_owner,contratpro_runtime,contratpro_platform_runtime,contratpro_agency_writer,contratpro_identity_writer;
GRANT EXECUTE ON FUNCTION public.contratpro_client_creation_contract() TO authenticated;

REVOKE CREATE ON SCHEMA app_private FROM contratpro_client_receipt_writer;
REVOKE contratpro_client_receipt_writer FROM postgres GRANTED BY postgres;
-- No clients column grants were added to ANY internal role. Protect this invariant.
DO $verify$
BEGIN
 IF NOT pg_catalog.has_schema_privilege('contratpro_client_receipt_writer','app_private','USAGE')
 OR pg_catalog.has_function_privilege('authenticated','app_private.match_client_creation(uuid,uuid,jsonb)','EXECUTE') IS DISTINCT FROM true
 OR NOT pg_catalog.has_language_privilege('contratpro_client_receipt_writer','plpgsql','USAGE')
 OR NOT pg_catalog.has_function_privilege('contratpro_client_receipt_writer','app_private.receipt_auth_uid()','EXECUTE')
 OR pg_catalog.has_schema_privilege('contratpro_client_receipt_writer','app_private','CREATE')
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE roleid='contratpro_client_receipt_writer'::pg_catalog.regrole
   AND (member<>'postgres'::pg_catalog.regrole OR grantor='postgres'::pg_catalog.regrole OR set_option OR inherit_option))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member='contratpro_client_receipt_writer'::pg_catalog.regrole)
 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='contratpro_client_receipt_writer'
   AND NOT (rolsuper OR rolbypassrls OR rolcanlogin OR rolcreatedb OR rolcreaterole OR rolreplication OR rolinherit))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles r CROSS JOIN pg_catalog.pg_attribute a
   WHERE r.rolname IN ('contratpro_migration_owner','contratpro_runtime','contratpro_platform_runtime','contratpro_agency_writer','contratpro_identity_writer','contratpro_client_receipt_writer')
   AND a.attrelid='tenancy.clients'::pg_catalog.regclass AND a.attnum>0 AND NOT a.attisdropped
   AND (pg_catalog.has_column_privilege(r.oid,a.attrelid,a.attnum,'SELECT') OR pg_catalog.has_column_privilege(r.oid,a.attrelid,a.attnum,'INSERT') OR pg_catalog.has_column_privilege(r.oid,a.attrelid,a.attnum,'UPDATE')))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid='app_private.client_creation_receipts'::pg_catalog.regclass
   AND (relowner<>'postgres'::pg_catalog.regrole OR NOT relrowsecurity OR NOT relforcerowsecurity))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_class c,LATERAL pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
   WHERE c.oid='app_private.client_creation_receipts'::pg_catalog.regclass AND a.grantee<>c.relowner
   AND NOT(a.grantee='contratpro_client_receipt_writer'::pg_catalog.regrole AND a.privilege_type IN ('SELECT','INSERT') AND NOT a.is_grantable))
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_attribute col,LATERAL pg_catalog.aclexplode(col.attacl) a
   WHERE col.attrelid='app_private.client_creation_receipts'::pg_catalog.regclass AND a.grantee<>'postgres'::pg_catalog.regrole)
 OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p,LATERAL pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
   WHERE p.oid IN ('app_private.capture_client_creation()'::pg_catalog.regprocedure,'app_private.match_client_creation(uuid,uuid,jsonb)'::pg_catalog.regprocedure)
   AND (p.proowner<>'contratpro_client_receipt_writer'::pg_catalog.regrole OR NOT p.prosecdef
     OR (p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp','row_security=on']) IS DISTINCT FROM true
     OR (a.grantee<>p.proowner AND NOT(p.proname='match_client_creation' AND a.grantee='authenticated'::pg_catalog.regrole AND a.privilege_type='EXECUTE' AND NOT a.is_grantable))))
 THEN RAISE EXCEPTION 'Client receipt capability boundary mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid IN (
  'app_private.canonical_auth_user()'::pg_catalog.regprocedure,'app_private.agency_owner(uuid)'::pg_catalog.regprocedure,
  'app_private.client_allowed(uuid,text)'::pg_catalog.regprocedure,'app_private.client_payload(tenancy.clients)'::pg_catalog.regprocedure,
  'app_private.client_guard()'::pg_catalog.regprocedure,
  'app_private.valid_client(jsonb)'::pg_catalog.regprocedure,'app_private.normalize_client_creation(jsonb)'::pg_catalog.regprocedure,
  'app_private.client_unicode_case(text,boolean)'::pg_catalog.regprocedure,'public.contratpro_client_create(uuid,uuid,jsonb)'::pg_catalog.regprocedure,
  'public.contratpro_client_creation_contract()'::pg_catalog.regprocedure,
  'public.contratpro_clients_permissions(uuid)'::pg_catalog.regprocedure,'public.contratpro_clients_list(uuid,text,text,integer,integer)'::pg_catalog.regprocedure,
  'public.contratpro_client_detail(uuid,uuid)'::pg_catalog.regprocedure,'public.contratpro_client_update(uuid,uuid,integer,jsonb)'::pg_catalog.regprocedure,
  'public.contratpro_client_archive(uuid,uuid,integer)'::pg_catalog.regprocedure)
  AND (p.prosecdef OR p.proowner<>'postgres'::pg_catalog.regrole OR (p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']) IS DISTINCT FROM true))
 THEN RAISE EXCEPTION 'Client invoker helper boundary mismatch'; END IF;
END;
$verify$;

-- V3: verify bridge owner, ACL and non-dependency on managed auth schema USAGE.
DO $v3_bridge_verify$
DECLARE
  bridge_oid oid := 'app_private.receipt_auth_uid()'::pg_catalog.regprocedure;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_proc p
    WHERE p.oid=bridge_oid
      AND p.proowner='postgres'::pg_catalog.regrole
      AND p.prosecdef
      AND p.provolatile='s'
      AND p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']
  ) THEN
    RAISE EXCEPTION 'V3 bridge security configuration mismatch';
  END IF;
  IF pg_catalog.has_function_privilege('PUBLIC',bridge_oid,'EXECUTE')
     OR NOT pg_catalog.has_function_privilege('contratpro_client_receipt_writer',bridge_oid,'EXECUTE')
     OR pg_catalog.has_schema_privilege('contratpro_client_receipt_writer','auth','USAGE')
  THEN
    RAISE EXCEPTION 'V3 bridge ACL boundary mismatch';
  END IF;
END;
$v3_bridge_verify$;

